*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111827;color:#fff;font-family:'DM Sans',sans-serif}button{font:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:440px;overflow:hidden;background:linear-gradient(180deg,#f1b18d 0%,#d89182 45%,#485464 100%)}#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,20,34,.34),transparent 20%,transparent 67%,rgba(13,20,34,.52)),radial-gradient(ellipse at 48% 47%,transparent 30%,rgba(14,19,30,.19) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:78px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.15);background:linear-gradient(180deg,rgba(14,19,31,.38),transparent)}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none}.brand-mark{width:37px;height:37px;display:grid;place-items:center;border:1.5px solid rgba(255,255,255,.72);border-radius:11px;font:700 18px 'Space Grotesk';position:relative}.brand-mark span{color:#ffd39e;font-size:12px;position:absolute;right:4px;top:1px}.brand-name{font:700 11px 'Space Grotesk';letter-spacing:1.4px;line-height:1.5}.brand-name b{display:block;color:#ffcf9f;font-size:9px;letter-spacing:2.4px}.top-center{font-size:10px;font-weight:700;letter-spacing:2.3px;color:rgba(255,255,255,.77);display:flex;align-items:center;gap:10px}.live-dot,.eyebrow span{width:7px;height:7px;border-radius:50%;background:#ffcc9a;box-shadow:0 0 12px #ffd0a0}.icon-button{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.09);color:white;cursor:pointer;font-size:19px}.hud{position:absolute;z-index:2;top:100px;left:4.2%;display:flex;gap:10px}.stat-card{padding:13px 17px 12px;background:rgba(19,26,39,.63);border:1px solid rgba(255,255,255,.19);border-radius:12px;backdrop-filter:blur(12px);min-width:176px;box-shadow:0 8px 30px rgba(13,19,30,.11)}.timer-card{min-width:112px}.stat-label{font-size:9px;letter-spacing:1.6px;font-weight:700;color:rgba(255,255,255,.67);display:flex;align-items:center;gap:7px}.mini-icon{color:#ffd19b;font-size:15px}.stat-value{margin-top:5px;font:700 25px 'Space Grotesk';letter-spacing:.3px}.stat-unit{font:700 9px 'DM Sans';letter-spacing:1.3px;color:rgba(255,255,255,.5);margin-left:7px}.progress-track{height:3px;background:rgba(255,255,255,.14);margin-top:9px;border-radius:4px;overflow:hidden}.progress-track i{height:100%;display:block;width:0;background:#ffca91;border-radius:4px;transition:width .35s}.objective-pill{position:absolute;top:104px;left:50%;transform:translateX(-50%);padding:10px 16px;border:1px solid rgba(255,255,255,.2);background:rgba(20,27,40,.46);border-radius:99px;backdrop-filter:blur(10px);font-size:11px;color:rgba(255,255,255,.84);letter-spacing:.2px;white-space:nowrap}.target-icon{font-size:16px;color:#ffcf9d;vertical-align:-1px;margin-right:8px}.controls-card{position:absolute;z-index:2;right:4.1%;top:103px;width:220px;padding:16px 17px 14px;border:1px solid rgba(255,255,255,.18);background:rgba(19,26,39,.58);border-radius:12px;backdrop-filter:blur(12px);box-shadow:0 8px 30px rgba(13,19,30,.11)}.controls-title{font:700 9px 'Space Grotesk';letter-spacing:1.9px;color:#ffcf9d;margin-bottom:12px;display:flex;justify-content:space-between}.controls-title span{font-size:13px}.control-row{display:flex;align-items:center;gap:4px;margin:6px 0;color:rgba(255,255,255,.8);font-size:10px}.control-row span{margin-left:7px}.control-row kbd{width:18px;height:19px;text-align:center;padding-top:3px;font:700 9px 'DM Sans';color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:4px;background:rgba(255,255,255,.08)}.control-row kbd.wide{width:49px;font-size:8px}.control-hint{margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.12);font-size:9px;line-height:1.5;color:rgba(255,255,255,.52)}.bottom-caption{position:absolute;z-index:2;bottom:26px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:9px;font-weight:700;letter-spacing:2.4px;color:rgba(255,255,255,.67);display:flex;align-items:center;gap:10px}.caption-star{color:#ffcf9d;font-size:15px}.caption-line{display:inline-block;width:38px;height:1px;background:rgba(255,255,255,.37)}.crosshair{position:absolute;left:50%;top:53%;width:19px;height:19px;border:1px solid rgba(255,255,255,.37);border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.crosshair span{position:absolute;left:50%;top:50%;width:3px;height:3px;background:#ffe1bc;border-radius:50%;transform:translate(-50%,-50%)}.overlay{position:absolute;z-index:5;inset:0;background:linear-gradient(90deg,rgba(14,20,31,.78),rgba(14,20,31,.46) 52%,rgba(14,20,31,.05));display:flex;align-items:center;padding:8vh 11.5%;transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.welcome-panel{width:min(440px,100%);padding:24px 0}.eyebrow{display:flex;align-items:center;gap:9px;color:#ffd2a7;font-size:9px;font-weight:700;letter-spacing:2.5px}.eyebrow span{width:6px;height:6px}h1,h2{font:700 clamp(46px,6.1vw,76px)/.99 'Space Grotesk',sans-serif;letter-spacing:-4px;margin:22px 0 18px;text-shadow:0 4px 26px rgba(0,0,0,.13)}h1 em,h2 em{font-style:normal;color:#ffcc97}.welcome-panel>p{max-width:390px;color:rgba(255,255,255,.76);font-size:13px;line-height:1.75;margin:0 0 24px}.welcome-details{display:flex;gap:25px;margin:24px 0 27px}.welcome-details>div{display:flex;align-items:center;gap:10px}.detail-icon{width:30px;height:30px;border-radius:9px;background:rgba(255,207,157,.12);color:#ffd09f;display:grid;place-items:center;font-size:18px}.welcome-details b,.welcome-details small{display:block}.welcome-details b{font-size:10px;font-weight:700}.welcome-details small{font-size:9px;color:rgba(255,255,255,.56);margin-top:3px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:24px;background:#ffd09f;color:#31271f;border:0;border-radius:7px;padding:0 19px;height:48px;min-width:245px;font:700 10px 'Space Grotesk';letter-spacing:1.2px;cursor:pointer;box-shadow:0 7px 25px rgba(255,190,130,.18);transition:transform .2s,background .2s}.primary-button:hover{transform:translateY(-2px);background:#ffdcba}.primary-button span{font-size:19px;font-weight:500}.start-note{margin-top:13px;color:rgba(255,255,255,.52);font-size:9px;letter-spacing:.35px}.start-note i{color:#ffcf9d;font-style:normal;padding:0 6px}.welcome-badge{position:absolute;right:5%;bottom:7%;font-size:9px;letter-spacing:1.7px;font-weight:700;color:rgba(255,255,255,.7);display:flex;gap:9px;align-items:center}.welcome-badge span{font-size:17px;color:#ffd09f}.end-panel h2{font-size:clamp(42px,5vw,62px)}.final-score{display:flex;flex-direction:column;gap:6px;margin:28px 0 24px;padding-top:17px;border-top:1px solid rgba(255,255,255,.2);width:245px}.final-score>span{font-size:9px;letter-spacing:2px;color:rgba(255,255,255,.6);font-weight:700}.final-score>b{font:700 29px 'Space Grotesk';color:#ffcc97}.final-score small{font:700 10px 'DM Sans';letter-spacing:1px;color:rgba(255,255,255,.6)}.toast{position:absolute;z-index:4;top:23%;left:50%;transform:translate(-50%,-8px);opacity:0;background:rgba(23,31,44,.8);border:1px solid rgba(255,255,255,.18);border-radius:99px;padding:9px 16px;font-size:11px;font-weight:700;letter-spacing:.4px;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.combo-toast{position:absolute;z-index:4;left:50%;top:38%;transform:translate(-50%,10px) scale(.8);opacity:0;text-align:center;color:#ffcf9d;font:700 27px 'Space Grotesk';text-shadow:0 3px 20px rgba(0,0,0,.4);pointer-events:none;transition:.22s}.combo-toast.show{opacity:1;transform:translate(-50%,0) scale(1)}.mobile-controls{display:none;position:absolute;z-index:3;left:18px;right:18px;bottom:24px;align-items:flex-end;justify-content:space-between}.dpad{width:125px;height:108px;position:relative}.dpad button{position:absolute;width:37px;height:34px;background:rgba(20,27,40,.55);border:1px solid rgba(255,255,255,.31);color:white;border-radius:9px;backdrop-filter:blur(8px);touch-action:none}.dpad button:nth-child(1){left:44px;top:0}.dpad button:nth-child(2){left:4px;top:37px}.dpad button:nth-child(3){left:44px;top:37px}.dpad button:nth-child(4){left:84px;top:37px}.stomp-button{width:76px;height:76px;border-radius:50%;display:flex;flex-direction:column;gap:3px;align-items:center;justify-content:center;color:#33251a;background:#ffcf9d;border:2px solid rgba(255,255,255,.72);box-shadow:0 5px 25px rgba(0,0,0,.25);touch-action:none}.stomp-button span{font-size:23px}.stomp-button b{font-size:8px;letter-spacing:1px}.mobile-controls button:active{transform:scale(.94);filter:brightness(1.15)}
@media(max-width:900px){.objective-pill{top:auto;bottom:90px}.controls-card{display:none}.hud{left:16px;top:88px}.stat-card{min-width:145px}.timer-card{min-width:98px}.topbar{height:65px;padding:0 16px}.overlay{padding:70px 8%}.welcome-badge{right:18px;bottom:18px}}
@media(max-width:600px){#game-shell{min-height:100dvh}.top-center{font-size:8px;letter-spacing:1.5px}.brand-name{font-size:9px}.brand-mark{width:33px;height:33px}.hud{top:78px;left:12px;gap:6px}.stat-card{padding:9px 11px 8px;min-width:128px;border-radius:9px}.timer-card{min-width:88px}.stat-label{font-size:8px}.stat-value{font-size:21px}.progress-track{margin-top:6px}.objective-pill{bottom:147px;top:auto;font-size:9px;padding:8px 12px;max-width:90%;overflow:hidden;text-overflow:ellipsis}.mobile-controls{display:flex;bottom:max(15px,env(safe-area-inset-bottom))}.bottom-caption{display:none}.overlay{align-items:flex-start;padding:18vh 8% 0;background:linear-gradient(90deg,rgba(14,20,31,.76),rgba(14,20,31,.42) 75%,rgba(14,20,31,.08))}.welcome-panel{padding:10px 0}.eyebrow{font-size:8px}h1{font-size:54px;margin:18px 0 14px;letter-spacing:-3px}.welcome-panel>p{font-size:11px;line-height:1.6;max-width:330px;margin-bottom:16px}.welcome-details{gap:15px;margin:16px 0 19px}.detail-icon{width:27px;height:27px}.welcome-details b{font-size:9px}.welcome-details small{font-size:8px}.primary-button{height:44px;min-width:230px}.start-note{font-size:8px}.welcome-badge{display:none}.crosshair{top:52%}.toast{top:30%}.combo-toast{top:36%}}
@media(max-height:650px) and (min-width:601px){.overlay{padding-top:45px;padding-bottom:45px}.welcome-panel{transform:scale(.88);transform-origin:left center}.hud{top:87px}.controls-card{top:88px}.topbar{height:65px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js';

const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#d99a86');
scene.fog = new THREE.FogExp2('#bd8d83', 0.0044);
const camera = new THREE.PerspectiveCamera(43, innerWidth / innerHeight, 0.1, 260);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.17;

const hemi = new THREE.HemisphereLight('#fff0d4', '#525c65', 2.25);
scene.add(hemi);
const sun = new THREE.DirectionalLight('#ffe3c3', 3.1);
sun.position.set(-42, 66, 34);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -78; sun.shadow.camera.right = 78;
sun.shadow.camera.top = 78; sun.shadow.camera.bottom = -78;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.025;
scene.add(sun);

const mats = {
  grass: new THREE.MeshStandardMaterial({ color: '#728b78', roughness: 1 }),
  asphalt: new THREE.MeshStandardMaterial({ color: '#50585d', roughness: 0.96 }),
  curb: new THREE.MeshStandardMaterial({ color: '#c4b8a4', roughness: 1 }),
  line: new THREE.MeshStandardMaterial({ color: '#e9d8a8', roughness: 1 }),
  sidewalk: new THREE.MeshStandardMaterial({ color: '#b8aa96', roughness: 1 }),
  skin: new THREE.MeshStandardMaterial({ color: '#d99b76', roughness: .88 }),
  skinLight: new THREE.MeshStandardMaterial({ color: '#edb18a', roughness: .83 }),
  hair: new THREE.MeshStandardMaterial({ color: '#4b2d2c', roughness: .93 }),
  top: new THREE.MeshStandardMaterial({ color: '#328b83', roughness: .8 }),
  skirt: new THREE.MeshStandardMaterial({ color: '#dc795d', roughness: .82 }),
  trim: new THREE.MeshStandardMaterial({ color: '#f5c18d', roughness: .7 }),
  white: new THREE.MeshStandardMaterial({ color: '#fff1dc', roughness: .5 }),
  eye: new THREE.MeshStandardMaterial({ color: '#39292c', roughness: .45 }),
};
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const sphereGeo = new THREE.SphereGeometry(1, 14, 10);
const cylinderGeo = new THREE.CylinderGeometry(1, 1, 1, 12);
const capsuleGeo = new THREE.CapsuleGeometry(.42, 1.7, 4, 8);
const cityObjects = [];
const particles = [];
const rings = [];

function mesh(geometry, material, parent, x=0, y=0, z=0, sx=1, sy=1, sz=1) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(x,y,z); m.scale.set(sx,sy,sz);
  m.castShadow = true; m.receiveShadow = true;
  parent.add(m); return m;
}
function block(parent, material, x,y,z,sx,sy,sz) { return mesh(boxGeo, material, parent,x,y,z,sx,sy,sz); }
function makeMat(color, rough=.88, metal=0) { return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal }); }
function rng(seed) { let a=seed>>>0; return () => { a=(a+0x6D2B79F5)|0; let t=Math.imul(a^(a>>>15),1|a); t^=t+Math.imul(t^(t>>>7),61|t); return ((t^(t>>>14))>>>0)/4294967296; }; }
const rand = rng(719031);
function pick(list) { return list[Math.floor(rand()*list.length)]; }

// A quiet patchwork of tiny blocks, broad streets, crosswalks, and miniature street furniture.
mesh(new THREE.PlaneGeometry(132,132), mats.grass, scene,0,-.17,0).rotation.x=-Math.PI/2;
for(let lane=-54;lane<=54;lane+=18){
  block(scene,mats.asphalt,lane,.005,0,6.6,.12,120);
  block(scene,mats.asphalt,0,.006,lane,120,.12,6.6);
  block(scene,mats.curb,lane-3.55,.055,0,.22,.15,120);
  block(scene,mats.curb,lane+3.55,.055,0,.22,.15,120);
  block(scene,mats.curb,0,.055,lane-3.55,120,.15,.22);
  block(scene,mats.curb,0,.055,lane+3.55,120,.15,.22);
}
const dashMat = makeMat('#e3d4a9',.95);
for(let row=-54;row<=54;row+=18){
  for(let p=-52;p<=52;p+=7.5){
    block(scene,dashMat,p,.082,row,3.0,.026,.13);
    block(scene,dashMat,row,.083,p,.13,.026,3.0);
  }
  // Crosswalk bars make intersections legible at a glance.
  for(let k=-2;k<=2;k++){
    block(scene,mats.white,row+k*.46,.088,row-4.1,.24,.025,1.8);
    block(scene,mats.white,row-4.1,.089,row+k*.46,1.8,.025,.24);
  }
}

const facades=['#d9bda0','#c8c0aa','#9facab','#d5a39a','#c9ad91','#aeb9a8','#d9c8ac','#b2a1a0','#d3b88f'];
const windowMats=['#84a2a3','#96b6b4','#789597','#d3bd9e','#8dabb0'].map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.48,metalness:.08,emissive:c,emissiveIntensity:.07}));
const roofMats=['#858782','#9a8d7a','#6f7978','#aa907c'].map(c=>makeMat(c));
function createBuilding(x,z){
  const g=new THREE.Group(); g.position.set(x,0,z); scene.add(g);
  const w=3.1+rand()*2.2, d=3.0+rand()*2.2, h=5+rand()*10.5;
  const facade=makeMat(pick(facades),.92);
  block(g,facade,0,h/2,0,w,h,d);
  // Carefully aligned rows of warmly lit windows on the street-facing sides.
  const cols=Math.max(2,Math.floor(w/1.05)), floors=Math.max(2,Math.floor(h/1.9));
  const wx=Math.min(.48,(w*.68)/cols), wy=Math.min(.55,(h*.64)/floors);
  for(let floor=0;floor<floors;floor++){
    const yy=1.05+floor*(h-1.6)/floors;
    for(let col=0;col<cols;col++){
      const xx=(col-(cols-1)/2)*(w*.75/cols);
      const wm=pick(windowMats);
      block(g,wm,xx,yy,-d/2-.012,wx,wy,.035);
      if(rand()>.15) block(g,wm,xx,yy,d/2+.012,wx,wy,.035);
    }
  }
  const sideCols=Math.max(2,Math.floor(d/1.35));
  for(let floor=0;floor<floors;floor++) for(let col=0;col<sideCols;col++){
    const yy=1.05+floor*(h-1.6)/floors;
    const zz=(col-(sideCols-1)/2)*(d*.72/sideCols);
    block(g,pick(windowMats),w/2+.012,yy,zz,.035,.43,.48);
  }
  const roof=block(g,pick(roofMats),0,h+.14,0,w+.18,.3,d+.18);
  if(rand()>.42){
    const box=block(g,facade,(rand()-.5)*w*.36,h+.55,(rand()-.5)*d*.3,.9,.55,.8);
    if(rand()>.5) mesh(cylinderGeo,roofMats[0],g,box.position.x,h+.98,box.position.z,.48,.35,.48);
  }
  // Tiny rooftop aerial.
  if(rand()>.75){
    const aerial=makeMat('#6e7471',.78,.18);
    mesh(cylinderGeo,aerial,g,w*.27,h+.72,d*.24,.045,.9,.045);
  }
  cityObjects.push({group:g,kind:'building',x,z,alive:true,points:150,fall:0,baseH:h});
}

function createCar(x,z,yaw){
  const g=new THREE.Group(); g.position.set(x,.12,z); g.rotation.y=yaw; scene.add(g);
  const color=pick(['#c96955','#e3b75b','#57878c','#d6d1bc','#748aa0','#bd8a68','#e2e0d1','#7f9272']);
  const bodyMat=makeMat(color,.53,.08), glass=makeMat('#47626a',.28,.13), tire=makeMat('#302f30',.98), hub=makeMat('#b9b8ad',.48,.3);
  block(g,bodyMat,0,.46,0,1.05,.48,2.0);
  block(g,bodyMat,0,.76,-.07,.83,.43,1.03);
  block(g,glass,0,.79,-.08,.85,.29,.82);
  block(g,makeMat('#eee0bd',.4),0,.41,-1.015,.4,.12,.028);
  for(const side of [-1,1]) for(const zz of [-.65,.66]){
    const wheel=mesh(cylinderGeo,tire,g,side*.54,.28,zz,.23,.17,.23); wheel.rotation.z=Math.PI/2;
    const center=mesh(cylinderGeo,hub,g,side*.64,.28,zz,.11,.08,.11); center.rotation.z=Math.PI/2;
  }
  const light=makeMat('#ffe6ae',.3,.05);
  block(g,light,-.32,.48,-1.025,.18,.13,.035); block(g,light,.32,.48,-1.025,.18,.13,.035);
  cityObjects.push({group:g,kind:'car',x,z,alive:true,points:45,fall:0,baseH:.12});
}
function createTree(x,z){
  const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
  const bark=makeMat('#826652'),leaves=makeMat(pick(['#627f68','#72896c','#88906d','#668075']));
  mesh(cylinderGeo,bark,g,0,.72,0,.24,1.45,.24);
  mesh(sphereGeo,leaves,g,0,1.95,0,.95,1.05,.9);
  mesh(sphereGeo,leaves,g,-.48,1.65,.14,.63,.74,.62);
  mesh(sphereGeo,leaves,g,.48,1.69,-.12,.62,.7,.62);
}
function createLamp(x,z,yaw=0){
  const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=yaw;scene.add(g);
  const metal=makeMat('#535c5c',.66,.25),bulb=new THREE.MeshStandardMaterial({color:'#fff1ca',emissive:'#ffdc9c',emissiveIntensity:.75});
  mesh(cylinderGeo,metal,g,0,1.75,0,.09,3.5,.09);
  mesh(cylinderGeo,metal,g,.35,3.35,-.3,.065,.75,.065).rotation.z=Math.PI/2.8;
  mesh(sphereGeo,bulb,g,.53,3.03,-.3,.22,.17,.22);
}

const centers=[];
for(let i=-45;i<=45;i+=18) centers.push(i);
for(const x of centers) for(const z of centers){
  const count=1+(rand()>.25?1:0)+(rand()>.79?1:0);
  for(let n=0;n<count;n++){
    const ox=(n%2===0?-1:1)*(2.2+rand()*2.1)+(rand()-.5)*1.1;
    const oz=(n<2?(rand()-.5)*4.3:(rand()>.5?1:-1)*3.0);
    createBuilding(x+ox,z+oz);
  }
  // A tree or a lamp at most corners softens the miniature streetscape.
  if(rand()>.37) createTree(x+(rand()>.5?1:-1)*5.35,z+(rand()>.5?1:-1)*5.35);
  else createLamp(x+(rand()>.5?1:-1)*4.9,z+(rand()>.5?1:-1)*4.9,rand()*Math.PI);
}
// Parked cars sit neatly along both sides of the little roads.
for(let n=0;n<37;n++){
  const lane=pick(centers);
  if(rand()>.5){
    const z=lane+(rand()>.5?1:-1)*2.05;
    createCar(-51+rand()*102,z,rand()>.5?0:Math.PI);
  }else{
